1	package importer
2	
3	import (
4		"strings"
5		"testing"
6	)
7	
8	func TestReadStock(t *testing.T) {
9		t.Parallel()
10	
11		t.Run("good rows", func(t *testing.T) {
12			t.Parallel()
13			rows, bad, err := ReadStock(strings.NewReader("Washer,200,pcs\nNut M6,50,boxes\n"))
14			if err != nil || len(bad) != 0 {
15				t.Fatalf("err=%v bad=%v", err, bad)
16			}
17			if len(rows) != 2 || rows[1] != (Row{Name: "Nut M6", Quantity: 50, Unit: "boxes"}) {
18				t.Fatalf("rows = %+v", rows)
19			}
20		})
21	
22		t.Run("quoted comma in name", func(t *testing.T) {
23			t.Parallel()
24			rows, bad, err := ReadStock(strings.NewReader("\"Bolt, M6\",40,pcs\n"))
25			if err != nil || len(bad) != 0 {
26				t.Fatalf("err=%v bad=%v", err, bad)
27			}
28			if len(rows) != 1 || rows[0].Name != "Bolt, M6" || rows[0].Quantity != 40 {
29				t.Fatalf("rows = %+v", rows)
30			}
31		})
32	
33		t.Run("short row skipped with line number", func(t *testing.T) {
34			t.Parallel()
35			rows, bad, err := ReadStock(strings.NewReader("Washer,200,pcs\nNut M6,50\n"))
36			if err != nil {
37				t.Fatal(err)
38			}
39			if len(rows) != 1 || len(bad) != 1 || bad[0].Line != 2 {
40				t.Fatalf("rows=%+v bad=%+v", rows, bad)
41			}
42		})
43	
44		t.Run("non numeric quantity skipped", func(t *testing.T) {
45			t.Parallel()
46			rows, bad, err := ReadStock(strings.NewReader("Washer,lots,pcs\n"))
47			if err != nil {
48				t.Fatal(err)
49			}
50			if len(rows) != 0 || len(bad) != 1 || bad[0].Line != 1 {
51				t.Fatalf("rows=%+v bad=%+v", rows, bad)
52			}
53		})
54	}
